package com.vibecode.output.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="task_evidence") public class TaskEvidence { @Id private UUID id; @Column(name="project_id",nullable=false) private UUID projectId; @Column(name="task_id",nullable=false) private UUID taskId; @Enumerated(EnumType.STRING) @Column(nullable=false) private EvidenceType type; @Column(name="raw_content",nullable=false,columnDefinition="TEXT") private String rawContent; @Column(nullable=false) private String source; @Column(name="created_at",nullable=false) private Instant createdAt; protected TaskEvidence(){} public TaskEvidence(UUID projectId,UUID taskId,EvidenceType type,String raw,String source){id=UUID.randomUUID();this.projectId=projectId;this.taskId=taskId;this.type=type;rawContent=raw;this.source=source;createdAt=Instant.now();} public UUID id(){return id;} public UUID taskId(){return taskId;} public String rawContent(){return rawContent;} public EvidenceType type(){return type;} public String source(){return source;} public Instant createdAt(){return createdAt;} }
